"""Manual EXPLAIN matrix against the disposable g162-plans container only.

Run from the repository root. Requires Python 3 and Docker; no Python dependencies.
Create the container as described in plans/README.md, then run:
  python3 dcb/tests/Sekiban.Dcb.Postgres.AppendBenchmark/plan_capture.py final
An optional second argument selects a different PostgresEventStore.cs snapshot.
SQL is extracted verbatim from that source, PREPAREd, EXPLAINed, then rolled back.
This recreates synthetic diagnostic tables, never the benchmark database.
"""
import re,json,subprocess,pathlib,sys
root=pathlib.Path.cwd(); out=root/'dcb/tests/Sekiban.Dcb.Postgres.AppendBenchmark/plans'
def psql(sql):
 r=subprocess.run(['docker','exec','-i','g162-plans','psql','-U','postgres','-X','-v','ON_ERROR_STOP=1'],input=sql,text=True,capture_output=True)
 if r.returncode: raise Exception(r.stderr)
 return r.stdout
schema='''DROP SCHEMA public CASCADE; CREATE SCHEMA public;
CREATE TABLE dcb_tags ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"ServiceId" varchar(64) NOT NULL,"Tag" text NOT NULL,"TagGroup" text NOT NULL,"EventType" text NOT NULL,"SortableUniqueId" varchar(100) NOT NULL,"EventId" uuid NOT NULL,"CreatedAt" timestamptz NOT NULL);
CREATE INDEX "IX_Tags_ServiceId" ON dcb_tags ("ServiceId"); CREATE INDEX "IX_Tags_Service_Tag" ON dcb_tags ("ServiceId","Tag"); CREATE INDEX "IX_Tags_SortableUniqueId" ON dcb_tags ("SortableUniqueId"); CREATE INDEX "IX_Tags_EventId" ON dcb_tags ("EventId"); CREATE INDEX "IX_Tags_Service_Tag_SortableUniqueId" ON dcb_tags ("ServiceId","Tag","SortableUniqueId");
CREATE TABLE dcb_tag_heads ("ServiceId" varchar(64) NOT NULL,"Tag" text NOT NULL,"HeadPosition" varchar(100),PRIMARY KEY("ServiceId","Tag"));
CREATE TABLE dcb_tag_head_violations ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"ServiceId" varchar(64) NOT NULL,"Tag" text NOT NULL,"PreviousHeadWasEmpty" boolean NOT NULL,"PreviousHeadPosition" varchar(100) NOT NULL,"ObservedPosition" varchar(100) NOT NULL,"DetectedAtUtc" timestamptz NOT NULL,"DetectingWriter" varchar(128) NOT NULL);
CREATE INDEX "IX_TagHeadViolations_Service_Tag_Detected" ON dcb_tag_head_violations ("ServiceId","Tag","DetectedAtUtc"); CREATE UNIQUE INDEX "UX_TagHeadViolations_IdempotentRepair" ON dcb_tag_head_violations ("ServiceId","Tag","PreviousHeadWasEmpty","PreviousHeadPosition","ObservedPosition");
'''
if 'init' in sys.argv: print(psql(schema));sys.exit()
source=pathlib.Path(sys.argv[2]).read_text() if len(sys.argv)>2 else (root/'dcb/src/Sekiban.Dcb.Postgres/PostgresEventStore.cs').read_text()
main=subprocess.check_output(['git','show','origin/main:dcb/src/Sekiban.Dcb.Postgres/PostgresEventStore.cs'],text=True)
def statements(src):
 # Read only SQL string concatenations, preserving production SQL verbatim.
 return [''.join(json.loads(s) for s in re.findall(r'"(?:[^"\\]|\\.)*"',m.group())) for m in re.finditer(r'"(?:SELECT|INSERT|UPDATE|DELETE) (?:[^"\\]|\\.)*"(?:\s*\+\s*"(?:[^"\\]|\\.)*")*',src)]
paramtypes={'serviceIds':'text[]','tags':'text[]','positions':'text[]','wasEmpty':'boolean[]','previous':'text[]','observed':'text[]','detectedAtUtc':'timestamptz','writer':'text','serviceId':'text','tag':'text','headPosition':'text','position':'text','wasEmptyScalar':'boolean','previousScalar':'text','observedScalar':'text'}
for n,writes,writers in [(1,2500,1),(5,1500,1),(20,1000,1),(1,3000,16),(5,13000,16)]:
 # 2.5k / 7.5k / 20k / 3k / 65k tag rows, fixed head cardinalities 1/5/20/16/80.
 psql(schema)
 setup='TRUNCATE dcb_tags,dcb_tag_heads,dcb_tag_head_violations RESTART IDENTITY;'
 setup+=f'''INSERT INTO dcb_tags ("ServiceId","Tag","TagGroup","EventType","SortableUniqueId","EventId","CreatedAt") SELECT 'benchmark','private:'||(i % {writers})||':'||t,'private','StudentCreated',lpad(i::text,20,'0'),'00000000-0000-0000-0000-000000000001',now() FROM generate_series(1,{writes}) i CROSS JOIN generate_series(0,{n-1}) t;
 INSERT INTO dcb_tag_heads SELECT "ServiceId","Tag",max("SortableUniqueId") FROM dcb_tags GROUP BY 1,2;'''
 print(psql(setup).strip())
 # Capture before ANALYZE too: benchmark never explicitly ANALYZEs; autoanalyze timing can change plan choice.
 for stats in ['fresh','analyzed']:
  if stats=='analyzed': psql('ANALYZE;')
  for label,src in [('main',main),('branch-'+sys.argv[1],source)]:
   queries=[q for q in statements(src) if 'dcb_tag_heads' in q or 'dcb_tag_head_violations' in q or (('MAX(' in q or 'FROM unnest(@serviceIds' in q) and 'dcb_tags' in q)]
   for mode in ['custom','generic']:
    sql='\\pset pager off\nSET plan_cache_mode=force_'+mode+'_plan;\n'
    arr=lambda xs:'ARRAY['+','.join("'"+x+"'" for x in xs)+']::text[]'
    vals={'serviceIds':arr(['benchmark']*n),'tags':arr(['private:0:'+str(i) for i in range(n)]),'positions':arr([f'{writes:020}']*n),'wasEmpty':'ARRAY['+','.join(['false']*n)+']','previous':arr(['00000000000000000001']*n),'observed':arr([f'{writes:020}']*n),'detectedAtUtc':"now()",'writer':"'TypedBatch'",'serviceId':"'benchmark'",'tag':"'private:0:0'",'headPosition':f"'{writes:020}'",'position':f"'{writes+1:020}'",'wasEmptyScalar':'false','previousScalar':"'00000000000000000001'",'observedScalar':f"'{writes:020}'"}
    for i,q in enumerate(queries):
     names=list(dict.fromkeys(re.findall(r'@(\w+)',q)))
     if label=='main':
      for old in ['wasEmpty','previous','observed']:
       if old in names:q=q.replace('@'+old,'@'+old+'Scalar')
      names=list(dict.fromkeys(re.findall(r'@(\w+)',q)))
     prepared=re.sub(r'@(\w+)',lambda m:'$'+str(names.index(m[1])+1),q)
     sql+=f"\\echo STATEMENT {i}: {q}\nBEGIN; PREPARE q{i} ({','.join(paramtypes[k] for k in names)}) AS {prepared};\nEXPLAIN (ANALYZE, BUFFERS) EXECUTE q{i}({','.join(vals[k] for k in names)});\n"
     # Also exercise null heads for reconciliation.
     if 'headPosition' in names or 'positions' in names and 'SELECT k.service_id' in q:
      nullvals=dict(vals,positions='ARRAY['+','.join(['NULL']*n)+']::text[]',headPosition='NULL')
      sql+=f"\\echo NULL HEAD\nEXPLAIN (ANALYZE, BUFFERS) EXECUTE q{i}({','.join(nullvals[k] for k in names)});\n"
     sql+=f'DEALLOCATE q{i}; ROLLBACK;\n'
    (out/f'{label}-{n}tags-{writers}writers-{stats}-{mode}.txt').write_text(psql(sql))
